<?php $purpose=\Chengyu\Core\Input::choice($_GET['purpose']??'register',['register','email']);if($purpose==='email'&&!$me){redirect(url('login'));} ?>
<section class="panel glass verify-page"><span class="eyebrow">A SMALL STEP / A SAFER ACCOUNT</span><h1><?= t('Verify your email') ?></h1><p><?= t('Request a code, then return to the original form in this same browser.') ?></p>
<?= form_start('email_code_request','','',false) . hidden('purpose',$purpose) ?><?php field('email','Email',$purpose==='email'?$me['email']:'','email',['required'=>'required','autocomplete'=>'email']);button('Send verification code','','message'); ?></form><p class="hint"><?= t('Valid for 10 minutes, in this browser only. Never share it.') ?></p><a class="text-link" href="<?= e(url($purpose==='email'?'profile':'register')) ?>"><?= t('Return to the form') ?><?= icon('arrow') ?></a></section>
